"""Numerical references generated by the original MATLAB wrapping routines."""

import hashlib
import importlib
import json
from pathlib import Path
import sys

import numpy as np
import pytest

sys.path.insert(0, str(Path(__file__).resolve().parents[1] / "src"))
from ctfire_py import matlab_wrapping
from ctfire_py.ct_reconstruction import ct_reconstruction

FIXTURES = Path(__file__).parent / "test_results" / "reconstruction_test_files"
CASES = json.loads((FIXTURES / "manifest.json").read_text())["cases"]


def cells(fixture, key):
    return [
        [fixture[f"{key}_{j}_{k}"] for k in range(count)]
        for j, count in enumerate(fixture[f"{key}_wedges"])
    ]


@pytest.fixture(params=CASES, ids=lambda case: case["file"])
def reference(request):
    case = request.param
    path = FIXTURES / case["file"]
    assert hashlib.sha256(path.read_bytes()).hexdigest() == case["sha256"]
    with np.load(path, allow_pickle=False) as arrays:
        yield arrays


def test_forward_matches_matlab_coefficients(reference):
    image = reference["input"]
    before = image.copy()
    actual = matlab_wrapping.forward(
        image, int(reference["scales"].item()), int(reference["angles"].item())
    )
    expected = cells(reference, "C")
    assert len(actual) == len(expected)
    for scale, expected_scale in zip(actual, expected):
        assert len(scale) == len(expected_scale)
        for wedge, expected_wedge in zip(scale, expected_scale):
            assert wedge.shape == expected_wedge.shape
            np.testing.assert_allclose(wedge, expected_wedge, rtol=2e-13, atol=5e-13)
    np.testing.assert_array_equal(image, before)
    # Includes ceil-derived defaults for non-power-of-two dimensions.
    if reference["angles"].item() == 16:
        default = matlab_wrapping.forward(image)
        for scale, default_scale in zip(actual, default):
            for wedge, default_wedge in zip(scale, default_scale):
                np.testing.assert_array_equal(wedge, default_wedge)


def test_inverse_matches_matlab_filtered_coefficients(reference):
    coefficients = cells(reference, "Ct")
    before = [[w.copy() for w in scale] for scale in coefficients]
    actual = matlab_wrapping.inverse(coefficients)
    np.testing.assert_allclose(
        actual.real, reference["reconstructed"], rtol=2e-13, atol=5e-13
    )
    for scale, saved in zip(coefficients, before):
        for wedge, original in zip(scale, saved):
            np.testing.assert_array_equal(wedge, original)


def test_roundtrip_matches_matlab(reference):
    actual = matlab_wrapping.inverse(
        matlab_wrapping.forward(
            reference["input"],
            int(reference["scales"].item()),
            int(reference["angles"].item()),
        )
    )
    np.testing.assert_allclose(actual, reference["roundtrip"], rtol=2e-13, atol=5e-13)
    np.testing.assert_allclose(actual, reference["input"], rtol=2e-13, atol=5e-13)


# Symmetric impulse coefficients tie at the 20% cutoff: FFT rounding changes
# which equal-magnitude entries survive. Its forward/inverse references above
# are tested separately; strict threshold integration uses the other inputs.
@pytest.mark.parametrize(
    "case",
    [c for c in CASES if c["integration_threshold_test"] and c["angles"] == 16],
    ids=lambda case: case["file"],
)
def test_reconstruction_matches_matlab(case, monkeypatch):
    monkeypatch.setitem(sys.modules, "curvelops", None)
    with np.load(FIXTURES / case["file"], allow_pickle=False) as arrays:
        # Fixtures with 8/32 angles exercise the transform independently;
        # CTrec_1 uses 16 angles.
        actual = ct_reconstruction(
            arrays["input"], "unused", 0.2, int(arrays["selected_scales"].item())
        )
        np.testing.assert_allclose(
            actual, arrays["reconstructed"], rtol=2e-13, atol=5e-13
        )


def test_package_exports_reconstruction_without_curvelops(monkeypatch):
    monkeypatch.setitem(sys.modules, "curvelops", None)
    package = importlib.import_module("ctfire_py")
    # Reload executes the optional-backend detection with curvelops unavailable.
    try:
        importlib.reload(package)
        assert package.HAS_CURVELOPS is False
        assert callable(package.ct_reconstruction)
        assert "ct_reconstruction" in package.__all__
        if package.HAS_FIBER_BACKEND:
            assert callable(package.ct_fire)
    finally:
        monkeypatch.undo()
        importlib.reload(package)
